#'
#' Summarize the drug effect across concentrations
#'
#'This function summarizes the normalized drug effect (viability) across multiple concentrations into a single value.
#'The summary is based on the normalized viability values, which require plate normalization as a prerequisite.
#'If the viability values have been corrected for incubation/edge effect, the function will normalize
#'both the corrected and uncorrected values and add a suffix, ‘.cor’, to the columns with the summary values.
#'
#' @param screenData the data frame containing screening data generated by \code{readScreen()} function
#' @param method a character string or a vector of character strings specifying the method to summarize the drug effects.
#'  There are currently three methods available: average, AUC, and IC50.
#'  The average method calculates the average drug effect across all concentrations.
#'  The AUC method calculates the normalized area under the dose-response curve using the trapezoidal method.
#'  The IC50 method first fits a robust four-parameter log-logistic model using the dr4pl package.
#'  Then, it summarizes the drug effect using the four parameters (upper limit, lower limit, slope, and IC50/EC50)
#'  and area under the sigmoid curve.
#'  You can use multiple methods simultaneously by specifying a vector of method names.
#'@param minConc, lower bound of concentrations for the integration of area under curve.
#'used for method = "IC50". See \code{sumIC50()}.
#'@param maxConc, upper bound of concentrations for the integration of area under curve.
# used for method = "IC50". See \code{sumIC50()}.
#' @export
#' @import dr4pl tidyr
#'
#' @return The following columns will be added to the input data frame depending on the user-specified summarizing methods:
#'
#' If \code{method = 'average'},
#'
#' \item{meanViab}{the averaged viability across all concentrations for a certain drug}
#'
#' If \code{method = 'AUC'}
#'
#' \item{AUC}{the area under the dose-response curve calculated by using the trapezoidal rule.}
#'
#' If \code{method = 'IC50'}
#'
#' \item{UpperLimit}{the upper limit of the fitted logistic model}
#' \item{IC50}{the half maximal inhibitory concentration (IC50), or the half maximal effective concentration (EC50), depends on the type of input data}
#' \item{Slope}{the slope of the fitted logistic model}
#' \item{lowerLimit}{the upper limit of the fitted logistic model}
#' \item{AUC}{the area under the fitted sigmoid doese-response curve}
#'
#' If the logistic model can not be fitted for a certain drug, the above four values will be set to NA.
#'
#' If a column that contains the edge/incubation effect corrected viability values is present in the input data frame,
#' the above columns with a suffix \code{.cor}, which represent the summarized values based
#' on edge/incubation corrected viabilities, will also be added to the input data frame.
#'
#' @examples
#' data(screenData_normalized)
#' screenData <- summariseScreen(screenData_normalized)
#'
#' # Please see the vignette for more information.



# transform to single drug screen, analysis both drug
# retain drug2 in negative control or concentration is 0


summariseScreenCombination <- function(screenData,
                                       negWell = c()
                                       method = c("bliss", "AUC", "IC50"),
                                       minConc = 0, maxConc = 15) {


  # step1. bliss score concentration, sample drug
  # step2. bliss syn bliss antagonistic

  # transform to single drug screen
  # no tidyverse

  # check if the 'normVal' column is present for plate normalization
  if (!"normVal" %in% colnames(screenData)) {
    stop("Column 'normVal' not found.
         Plate normalization should be performed first")
  }

  # check if the 'normVal.cor' column is present
  ifCor <- "normVal.cor" %in% colnames(screenData)

  # only summarize the non-control wells
  subData <- screenData[screenData$wellType %in% "sample", ]

  # combination

  comTab <- filter(screenSub, !drug %in% negWell, !drug2 %in% negWell) %>%
    select(Name, Drug_A, Drug_A.Conc, Drug_B, Drug_B.Conc, normVal) %>%
    dplyr::rename(viabObs = normVal) %>%
    distinct(Name, Drug_A, Drug_A.Conc, Drug_B, Drug_B.Conc, .keep_all = TRUE)

  drugATab <- filter(screenSub, Drug_A != "DMSO", Drug_B == "DMSO") %>%
    select(Name, Drug_A, Drug_A.Conc, normVal, Drug_A.ConcStep) %>%
    dplyr::rename(viabA = normVal) %>%
    distinct(Name, Drug_A, Drug_A.Conc, .keep_all = TRUE)

  drugBTab <- filter(screenSub, Drug_A == "DMSO", Drug_B != "DMSO") %>%
    select(Name, Drug_B, Drug_B.Conc, normVal, Drug_B.ConcStep) %>%
    dplyr::rename(viabB = normVal) %>%
    distinct(Name, Drug_B, Drug_B.Conc, .keep_all = TRUE)


  # get the mean by concentration
  # drug combinations or single drug
  if (ifCor) {
    subData <- group_by(subData, sampleID, drug, drug2,
                        concentration, concentration2) %>%
      summarise(viab = mean(normVal, na.rm = TRUE),
                viab.cor = mean(normVal.cor, na.rm = TRUE)) %>%
      ungroup()
  } else {
    subData <- group_by(subData, sampleID, drug, drug2,
                        concentration, concentration2) %>%
      summarise(viab = mean(normVal, na.rm = TRUE)) %>%
      ungroup()
  }




  # summarize average, IC50 and AUC
  # drug combinations or single drug

  # "average" in method
  if ("average" %in% method) {
    if (ifCor) {
      sumTab <- group_by(subData, sampleID, drug, drug2) %>%
        dplyr::summarise(meanViab = mean(viab, na.rm = TRUE),
                         meanViab.cor = mean(viab.cor)) %>%
        ungroup()
    } else {
      sumTab <- group_by(subData, sampleID, drug, drug2)  %>%
        dplyr::summarise(meanViab = mean(viab, na.rm = TRUE)) %>%
        ungroup()
    }

    # Remove existing 'meanViab' column if it already exists in the input data
    if ("meanViab" %in% colnames(screenData))
      screenData[["meanViab"]] <- NULL

    # Join the summarized data back to the original data
    screenData <- left_join(screenData, sumTab,
                            by = c("sampleID", "drug", "drug2"))
  }

  # AUC in method
  if ("AUC" %in% method){
    if (ifCor) {
      # calcualte the AUC for two concentrations independently
      sumTab <- group_by(subData, sampleID, drug) %>%
        dplyr::summarise(AUC = calcAUC(viab, concentration),
                         AUC.cor = calcAUC(viab.cor, concentration)) %>%
        ungroup() %>%
        bind_cols(
          group_by(subData, sampleID, drug2) %>%
            dplyr::summarise(AUC2 = calcAUC(viab, concentration2),
                             AUC.cor2 = calcAUC(viab.cor, concentration2)) %>%
            ungroup() %>%
            select(AUC2, AUC.cor2))

    } else {
      sumTab <- group_by(subData, sampleID, drug) %>%
        dplyr::summarise(AUC = calcAUC(viab, concentration)) %>%
        ungroup() %>%
        bind_cols(
          group_by(subData, sampleID, drug2) %>%
            dplyr::summarise(AUC2 = calcAUC(viab, concentration2)) %>%
            ungroup() %>%
            select(AUC2))
    }

    # Remove existing 'AUC' column if it already exists in the input data
    if (any(c("AUC", "AUC2") %in% colnames(screenData))) {

      warning(paste0(intersect(c("AUC", "AUC2"),
                               colnames(screenData)), collapse = ","),
              " in original input data will be replaced by newly calcualted AUC/AUC2")

      screenData[,c("AUC", "AUC2")] <- NULL
    }

    # Join the summarized data back to the original data
    screenData <- left_join(screenData, sumTab,
                            by = c("sampleID", "drug", "drug2"))
  }

  # IC50, marginal IC50
  if ("IC50" %in% method) {

    # Group and nest the data for IC50 calculation
    sumTab <- group_by(subData, sampleID, drug) %>%
      nest() %>%
      dplyr::mutate(model = purrr::map(data,
                                       ~ sumIC50(viab ~ concentration, data = .,
                                                 minConc = minConc,
                                                 maxConc = maxConc))) %>%
      tidyr::unnest("model") %>%
      ungroup() %>%
      bind_cols(
        group_by(subData, sampleID, drug2) %>%
          nest() %>%
          dplyr::mutate(model2 = purrr::map(data,
                                            ~ sumIC50(viab ~ concentration2,
                                                      data = .,
                                                      minConc = minConc,
                                                      maxConc = maxConc))) %>%
          tidyr::unnest("model2") %>%
          ungroup() %>%
          dplyr::select(model2)
      )

    sumTab$data <- NULL

    if (ifCor) {

      sumTab.cor <- group_by(subData, sampleID, drug) %>%
        nest() %>%
        dplyr::mutate(model = purrr::map(data,
                                         ~ sumIC50(viab.cor ~ concentration,
                                                   data = .,
                                                   minConc = minConc,
                                                   maxConc = maxConc))) %>%
        tidyr::unnest("model") %>%
        ungroup() %>%
        bind_cols(
          group_by(subData, sampleID, drug2) %>%
            nest() %>%
            dplyr::mutate(model2 = purrr::map(data,
                                              ~ sumIC50(viab.cor ~ concentration2,
                                                        data = .,
                                                        minConc = minConc,
                                                        maxConc = maxConc))) %>%
            tidyr::unnest("model2") %>%
            ungroup() %>%
            dplyr::select(model2)
        )

      sumTab.cor$data <- NULL
      newColName <- colnames(sumTab.cor)

      newColName[!newColName %in% c("sampleID", "drug", "drug2")] <-
        paste0(newColName[!newColName %in% c("sampleID", "drug", "drug2")], ".cor")

      colnames(sumTab.cor) <- newColName
      sumTab <- left_join(sumTab, sumTab.cor, by = c("sampleID", "drug", "drug2"))

    for (colN in c("UpperLimit", "IC50", "Slope", "LowerLimit", "AUC")) {
      if (colN %in% colnames(screenData))
        screenData[[colN]] <- NULL
    }

    # Join the summarized IC50 data back to the original data
    screenData <- left_join(screenData, sumTab, by = c("sampleID", "drug", "drug2"))
    }
  }
  return(screenData)
}


summariseScreenSingleDrug <- function(screenData,
                                      method = c("average", "AUC", "IC50")) {

  # transform to single drug screen, analysis both drug
  # retain drug2 in negative control or concentration is 0

  # Check if the 'normVal.cor' column is present
  ifCor <- "normVal.cor" %in% colnames(screenData)

  # Only summarize the non-control wells
  subData <- screenData[screenData$wellType %in% "sample", ]

  # get the mean by concentration
  # drug combinations or single drug
  if (ifCor) {
    subData <- group_by(subData, sampleID, drug, concentration) %>%
      summarise(viab = mean(normVal, na.rm = TRUE),
                viab.cor = mean(normVal.cor, na.rm = TRUE)) %>%
      ungroup()
  } else {
    subData <- group_by(subData, sampleID, drug, concentration) %>%
      summarise(viab = mean(normVal, na.rm = TRUE)) %>%
      ungroup()
  }

  # summarize average, IC50 and AUC
  # drug combinations or single drug
  grouped_subData <- group_by(subData, sampleID, drug)

  # "average" in method
  if ("average" %in% method) {
    if (ifCor) {
      sumTab <- grouped_subData %>%
        dplyr::summarise(meanViab = mean(viab, na.rm = TRUE),
                         meanViab.cor = mean(viab.cor)) %>%
        ungroup()
    } else {
      sumTab <- grouped_subData %>%
        dplyr::summarise(meanViab = mean(viab, na.rm = TRUE)) %>%
        ungroup()
    }

    # Remove existing 'meanViab' column if it already exists in the input data
    if ("meanViab" %in% colnames(screenData))
      screenData[["meanViab"]] <- NULL

    # Join the summarized data back to the original data
    screenData <- left_join(screenData, sumTab,
                            by = c("sampleID", "drug"))
  }

  # "AUC" in method
  if ("AUC" %in% method) {
    if (ifCor) {
      sumTab <- grouped_subData %>%
        dplyr::summarise(AUC = calcAUC(viab, concentration),
                         AUC.cor = calcAUC(viab.cor, concentration)) %>%
        ungroup()
    } else {
      sumTab <- grouped_subData %>%
        dplyr::summarise(AUC = calcAUC(viab, concentration)) %>%
        ungroup()
    }

    # Remove existing 'AUC' column if it already exists in the input data
    if ("AUC" %in% colnames(screenData))
      screenData[["AUC"]] <- NULL

    screenData <- left_join(screenData, sumTab,
                            by = c("sampleID", "drug"))
  }

  # "IC50" in method
  if ("IC50" %in% method) {
    # Group and nest the data for IC50 calculation
    sumTab <- grouped_subData %>%
      nest() %>%
      dplyr::mutate(model = purrr::map(data, ~ sumIC50(viab ~ concentration,
                                                       data = .,
                                                       minConc = 0,
                                                       maxConc = 15))) %>%
      tidyr::unnest("model") %>%
      ungroup()

    sumTab$data <- NULL

    if (ifCor) {
      sumTab.cor <- grouped_subData %>%
        nest() %>%
        dplyr::mutate(model = purrr::map(data, ~ sumIC50(viab.cor ~ concentration,
                                                         data = .,
                                                         minConc = 0,
                                                         maxConc = 15))) %>%
        tidyr::unnest("model") %>%
        ungroup()

      sumTab.cor$data <- NULL
      newColName <- colnames(sumTab.cor)
      newColName[!newColName %in% c("sampleID", "drug")] <-
        paste0(newColName[!newColName %in% c("sampleID", "drug")], ".cor")

      colnames(sumTab.cor) <- newColName
      sumTab <- left_join(sumTab, sumTab.cor, by = c("sampleID", "drug"))
    }

    for (colN in c("UpperLimit", "IC50", "Slope", "LowerLimit", "AUC")) {
      if (colN %in% colnames(screenData))
        screenData[[colN]] <- NULL
    }

    # Join the summarized IC50 data back to the original data
    screenData <- left_join(screenData, sumTab, by = c("sampleID", "drug"))
  }

  return(screenData)
}





